// Natural Earth 110m land grid (1-degree bitpack), ported from the shard
// live map (c0mpute data-site/network.html) so the finale globe is the real
// earth-dot aesthetic, not a generic sphere. 8100 bytes -> 64800 bits.
const LAND_B64 =
  '';

export function sph(lon: number, lat: number): [number, number, number] {
  const D2R = Math.PI / 180;
  const la = lat * D2R, lo = lon * D2R, cl = Math.cos(la);
  return [cl * Math.sin(lo), Math.sin(la), cl * Math.cos(lo)];
}

function decode(): Float32Array {
  const raw = atob(LAND_B64);
  const by = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) by[i] = raw.charCodeAt(i);
  const g = new Uint8Array(64800);
  for (let i = 0; i < 64800; i++) g[i] = (by[i >> 3] >> (7 - (i & 7))) & 1;
  const a: number[] = [];
  for (let row = 0; row < 180; row++)
    for (let col = 0; col < 360; col++)
      if (g[row * 360 + col]) {
        const lon = col - 180 + 0.5;
        const lat = 90 - row - 0.5;
        const p = sph(lon, lat);
        a.push(p[0], p[1], p[2]);
      }
  return new Float32Array(a);
}

let _land: Float32Array | null = null;
export function land(): Float32Array {
  if (!_land) _land = decode();
  return _land;
}

// 0.5-degree densified grid (each land cell -> 4 sub-dots): same coastline,
// 4x the texture, for close-up camera work where the 1-degree grid reads as
// sparse noise. Built lazily from the same bitpack.
// 2-degree coarse grid (every 2nd row and column): for small globes where
// the 1-degree grid meshes into solid fill.
let _coarse: Float32Array | null = null;
export function landCoarse(): Float32Array {
  if (!_coarse) {
    const raw = atob(LAND_B64);
    const by = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) by[i] = raw.charCodeAt(i);
    const g = new Uint8Array(64800);
    for (let i = 0; i < 64800; i++) g[i] = (by[i >> 3] >> (7 - (i & 7))) & 1;
    const a: number[] = [];
    for (let row = 0; row < 180; row += 2)
      for (let col = 0; col < 360; col += 2)
        if (g[row * 360 + col]) {
          const p2 = sph(col - 180 + 0.5, 90 - row - 0.5);
          a.push(p2[0], p2[1], p2[2]);
        }
    _coarse = new Float32Array(a);
  }
  return _coarse;
}

let _dense: Float32Array | null = null;
export function landDense(): Float32Array {
  if (!_dense) {
    const raw = atob(LAND_B64);
    const by = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) by[i] = raw.charCodeAt(i);
    const g = new Uint8Array(64800);
    for (let i = 0; i < 64800; i++) g[i] = (by[i >> 3] >> (7 - (i & 7))) & 1;
    const a: number[] = [];
    for (let row = 0; row < 180; row++)
      for (let col = 0; col < 360; col++)
        if (g[row * 360 + col]) {
          const lon = col - 180 + 0.5;
          const lat = 90 - row - 0.5;
          for (const dlon of [-0.25, 0.25])
            for (const dlat of [-0.25, 0.25]) {
              const q = sph(lon + dlon, lat + dlat);
              a.push(q[0], q[1], q[2]);
            }
        }
    _dense = new Float32Array(a);
  }
  return _dense;
}
